using System;

public static class GNSheld
{
    public static double RimAlpha(double normalDotView, double strength)
    {
        double dot = Math.Abs(normalDotView);
        dot = Math.Max(0.0, Math.Min(1.0, dot));
        double s = Math.Max(0.0, Math.Min(1.0, strength));
        double rim = Math.Pow(1.0 - dot, 3.0) * 0.9 * s;
        return rim;
    }
}
```

Note: `dot` is |N·V|. Front facing = dot ~1 → 1-dot ~0 → RimAlpha ~0. Rim = dot ~0 → 1-dot ~1 → max rim.
